function bucketSort(a, bucketCount = 5) {
  if (a.length === 0) return a;
  const min = Math.min(...a), max = Math.max(...a);
  const size = (max - min) / bucketCount || 1;
  const buckets = Array.from({ length: bucketCount + 1 }, () => []);
  for (const x of a) buckets[Math.floor((x - min) / size)].push(x);
  const result = [];
  for (const b of buckets) {
    b.sort((p, q) => p - q);
    result.push(...b);
  }
  return result;
}

