#include <stdio.h>

void insertionSort(float a[], int n) {
    for (int i = 1; i < n; i++) {
        float k = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > k) { a[j + 1] = a[j]; j--; }
        a[j + 1] = k;
    }
}

void bucketSort(float a[], int n) {
    float buckets[n][n];
    int cnt[n];
    for (int i = 0; i < n; i++) cnt[i] = 0;
    for (int i = 0; i < n; i++) {
        int b = (int)(n * a[i]);
        buckets[b][cnt[b]++] = a[i];
    }
    for (int i = 0; i < n; i++) insertionSort(buckets[i], cnt[i]);
    int idx = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < cnt[i]; j++) a[idx++] = buckets[i][j];
}

int main() {
    float a[] = {0.897f, 0.565f, 0.656f, 0.1234f, 0.665f, 0.3434f};
    bucketSort(a, 6);
    for (int i = 0; i < 6; i++) printf("%.3f ", a[i]);
    return 0;
}

