#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void bucketSort(vector<float>& arr) {
    int n = arr.size();
    vector<vector<float>> buckets(n);
    for (float v : arr) buckets[(int)(n * v)].push_back(v);
    for (auto& b : buckets) sort(b.begin(), b.end());
    int idx = 0;
    for (auto& b : buckets)
        for (float v : b) arr[idx++] = v;
}

int main() {
    vector<float> a = {0.897f, 0.565f, 0.656f, 0.1234f, 0.665f, 0.3434f};
    bucketSort(a);
    for (float v : a) printf("%.3f ", v);
    return 0;
}
